blocs/consent-field/style.css.content:
consent-field {
    display: block;
    color: var(--text-default, currentColor);
    font: inherit;
}

consent-field .consent-field__requirements {
    display: grid;
    gap: 0.75rem;
    min-width: 0;
    margin: 0;
    padding: 0;
    border: 0;
}

consent-field .consent-field__legend {
    margin-block-end: 0.25rem;
    font-weight: 700;
}

consent-field[appearance="compact"] .consent-field__legend {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
}

consent-field .consent-field__item {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    gap: 0.6rem;
    align-items: start;
    line-height: 1.45;
    cursor: pointer;
}

consent-field [data-consent-copy] {
    display: inline;
}

consent-field .consent-field__item input {
    width: 1rem;
    height: 1rem;
    margin-block-start: 0.2em;
    accent-color: var(--primary-base, #176b52);
}

consent-field .consent-field__item a {
    color: var(--primary-base, #176b52);
    font-weight: 650;
    text-underline-offset: 0.15em;
}

consent-field .consent-field__new-tab {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    clip-path: inset(50%);
    white-space: nowrap;
    border: 0;
}

consent-field .consent-field__status,
consent-field .consent-field__error,
consent-field .consent-field__changed,
consent-field .consent-field__required {
    margin: 0;
    font-size: 0.875rem;
}

consent-field .consent-field__status {
    color: var(--text-muted, #69726d);
}

consent-field .consent-field__error,
consent-field .consent-field__changed,
consent-field .consent-field__required {
    color: var(--danger-base, #a32626);
}

consent-field .consent-field__error {
    display: flex;
    flex-wrap: wrap;
    gap: 0.6rem;
    align-items: center;
}

consent-field [data-consent-retry] {
    min-height: 2rem;
    padding: 0.3rem 0.7rem;
    border: 1px solid currentColor;
    border-radius: 0.35rem;
    color: inherit;
    background: transparent;
    font: inherit;
    font-weight: 650;
    cursor: pointer;
}

consent-field [data-consent-editor-preview] {
    display: none;
}

cms-binding-core[cms-binding-disabled] consent-field [data-consent-runtime],
[cms-bind-stop] consent-field [data-consent-runtime],
consent-field[cms-binding-disabled] [data-consent-runtime],
consent-field[cms-bind-stop] [data-consent-runtime] {
    display: none !important;
}

cms-binding-core[cms-binding-disabled] consent-field [data-consent-editor-preview],
[cms-bind-stop] consent-field [data-consent-editor-preview],
consent-field[cms-binding-disabled] [data-consent-editor-preview],
consent-field[cms-bind-stop] [data-consent-editor-preview] {
    display: block !important;
}

