import { requiredEnv } from "./env.ts";
import { HttpError } from "./errors.ts";

export function requireCmsRequest(request: Request): void {
    const expected = requiredEnv("CMS_CONSENT_API_KEY");
    const authorization = request.headers.get("authorization") ?? "";
    const token = authorization.startsWith("Bearer ") ? authorization.slice(7).trim() : "";
    if (!token || !safeEqual(token, expected)) {
        throw new HttpError(401, "invalid CMS API key");
    }
}

export async function subjectClaimHash(value: string): Promise<string> {
    const normalized = value.trim().toLowerCase();
    if (!normalized || normalized.length > 320 || !normalized.includes("@")) {
        throw new HttpError(400, "subjectClaim must be a valid email address");
    }
    const key = await crypto.subtle.importKey(
        "raw",
        new TextEncoder().encode(requiredEnv("CMS_CONSENT_API_KEY")),
        { name: "HMAC", hash: "SHA-256" },
        false,
        ["sign"],
    );
    const payload = new TextEncoder().encode(`cms-consent-subject-claim-v1\0${normalized}`);
    const digest = await crypto.subtle.sign("HMAC", key, payload);
    return [...new Uint8Array(digest)].map((byte) => byte.toString(16).padStart(2, "0")).join("");
}

function safeEqual(left: string, right: string): boolean {
    if (left.length !== right.length) {
        return false;
    }
    let result = 0;
    for (let index = 0; index < left.length; index += 1) {
        result |= left.charCodeAt(index) ^ right.charCodeAt(index);
    }
    return result === 0;
}

import { HttpError } from "./errors.ts";
import { isRecord } from "./records.ts";

export function requiredEnv(name: string): string {
    const value = Deno.env.get(name);
    if (!value) {
        throw new HttpError(500, `missing ${name}`);
    }
    return value;
}

export function serviceRoleKey(): string {
    const keys = Deno.env.get("SUPABASE_SECRET_KEYS");
    if (keys) {
        const trimmed = keys.trim();
        if (!trimmed.startsWith("{")) {
            const first = trimmed
                .split(",")
                .map((value) => value.trim())
                .find(Boolean);
            if (first) {
                return first;
            }
        } else {
            let parsed: unknown;
            try {
                parsed = JSON.parse(trimmed);
            } catch {
                throw new HttpError(500, "SUPABASE_SECRET_KEYS must be valid JSON");
            }
            if (isRecord(parsed)) {
                if (typeof parsed.default === "string" && parsed.default) {
                    return parsed.default;
                }
                const first = Object.values(parsed).find((value) => typeof value === "string" && value);
                if (typeof first === "string") {
                    return first;
                }
            }
        }
    }
    const modernKey = Deno.env.get("SUPABASE_SECRET_KEY");
    if (modernKey) {
        return modernKey;
    }
    return requiredEnv("SUPABASE_SERVICE_ROLE_KEY");
}

export class HttpError extends Error {
    constructor(
        readonly status: number,
        message: string,
    ) {
        super(message);
    }
}

import { HttpError } from "./errors.ts";

export function json(data: unknown, status = 200): Response {
    return new Response(JSON.stringify(data), {
        status,
        headers: {
            "cache-control": "no-store",
            "content-type": "application/json; charset=utf-8",
        },
    });
}

export async function withMethod(
    request: Request,
    method: string,
    handler: () => Promise<Response>,
): Promise<Response> {
    if (request.method !== method) {
        return json({ error: "method not allowed" }, 405);
    }
    return handler();
}

export function handleError(error: unknown): Response {
    if (error instanceof HttpError) {
        return json({ error: error.message }, error.status);
    }
    return json({ error: "internal error" }, 500);
}

import { HttpError } from "../errors.ts";
import type { ConsentDocumentReference, VerifiedConsentDocument } from "../types.ts";
import { publishedPageContentHash } from "./hashing.ts";
import { materializeDocumentReferences, parsePublishedPageSnapshot, unavailable } from "./validation.ts";

const maximumResponseBytes = 2_100_000;
const maximumAggregateContentBytes = 8_388_608;
const maximumConcurrentFetches = 4;
const fetchTimeoutMilliseconds = 4_000;

export async function fetchResolvedDocuments(value: unknown): Promise<{
    documents: Array<VerifiedConsentDocument & { enabled: boolean }>;
    snapshotOrigin: string | null;
}> {
    const references = materializeDocumentReferences(value);
    const documents = new Array<VerifiedConsentDocument & { enabled: boolean }>(references.documents.length);
    let nextIndex = 0;
    let aggregateBytes = 0;
    const worker = async (): Promise<void> => {
        while (nextIndex < references.documents.length) {
            const index = nextIndex++;
            const reference = references.documents[index]!;
            const snapshot = await fetchSnapshot(reference);
            aggregateBytes += new TextEncoder().encode(snapshot.page.content).byteLength;
            if (aggregateBytes > maximumAggregateContentBytes) {
                unavailable();
            }
            documents[index] = { ...reference, page: snapshot.page, contentHash: snapshot.contentHash };
        }
    };
    await Promise.all(Array.from({ length: Math.min(maximumConcurrentFetches, references.documents.length) }, worker));
    return { documents, snapshotOrigin: references.snapshotOrigin };
}

async function fetchSnapshot(reference: ConsentDocumentReference) {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), fetchTimeoutMilliseconds);
    try {
        const response = await fetch(reference.publishedSnapshotUrl, {
            headers: { accept: "application/json" },
            redirect: "error",
            signal: controller.signal,
        });
        if (!response.ok || !response.headers.get("content-type")?.toLowerCase().includes("application/json")) {
            unavailable();
        }
        const snapshot = parsePublishedPageSnapshot(await boundedText(response), reference.pageId);
        if ((await publishedPageContentHash(snapshot.page)) !== snapshot.contentHash) {
            unavailable();
        }
        return snapshot;
    } catch (error) {
        if (error instanceof HttpError) {
            throw error;
        }
        unavailable();
    } finally {
        clearTimeout(timeout);
    }
}

async function boundedText(response: Response): Promise<string> {
    const declared = Number(response.headers.get("content-length"));
    if (Number.isFinite(declared) && declared > maximumResponseBytes) {
        unavailable();
    }
    const reader = response.body?.getReader();
    if (!reader) {
        unavailable();
    }
    const decoder = new TextDecoder();
    let size = 0;
    let result = "";
    while (true) {
        const chunk = await reader.read();
        if (chunk.done) {
            break;
        }
        size += chunk.value.byteLength;
        if (size > maximumResponseBytes) {
            await reader.cancel();
            unavailable();
        }
        result += decoder.decode(chunk.value, { stream: true });
    }
    return result + decoder.decode();
}

import { HttpError } from "../errors.ts";
import type { PublishedPage, VerifiedConsentDocument } from "../types.ts";

const maximumAggregateContentBytes = 8_388_608;

export async function hashResolvedDocuments(
    documents: Array<VerifiedConsentDocument & { enabled: boolean }>,
): Promise<Array<VerifiedConsentDocument & { enabled: boolean }>> {
    let aggregateBytes = 0;
    const result = await Promise.all(
        documents.map(async (document) => {
            aggregateBytes += new TextEncoder().encode(document.page.content).byteLength;
            if (aggregateBytes > maximumAggregateContentBytes) {
                throw new HttpError(422, "consent document content exceeds 8 MiB");
            }
            return { ...document, contentHash: await publishedPageContentHash(document.page) };
        }),
    );
    return result;
}

export async function publishedPageContentHash(page: PublishedPage): Promise<string> {
    const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(JSON.stringify(page)));
    return [...new Uint8Array(digest)].map((byte) => byte.toString(16).padStart(2, "0")).join("");
}

export { fetchResolvedDocuments } from "./fetch.ts";
export { hashResolvedDocuments, publishedPageContentHash } from "./hashing.ts";
export { materializeResolvedDocuments } from "./validation.ts";

import { HttpError } from "../errors.ts";

const snapshotRoute = "/.cms/content/published-page-snapshot";

export function pageIdFromSnapshotUrl(value: string): string {
    try {
        const url = new URL(value);
        const id = url.searchParams.get("id") ?? "";
        if (
            !isAllowedOrigin(url) ||
            url.username ||
            url.password ||
            url.hash ||
            !url.pathname.endsWith(snapshotRoute) ||
            [...url.searchParams.keys()].some((key) => key !== "id") ||
            url.searchParams.getAll("id").length !== 1 ||
            !id.trim() ||
            id.length > 512
        ) {
            invalidUrl();
        }
        return id;
    } catch (error) {
        if (error instanceof HttpError) {
            throw error;
        }
        invalidUrl();
    }
}

function invalidUrl(): never {
    throw new HttpError(422, "consent document URL is not a trusted published snapshot");
}

function isAllowedOrigin(url: URL): boolean {
    const hostname = url.hostname.toLowerCase();
    if (url.protocol === "http:") {
        return isLocalDevelopmentHost(hostname) && isLocalSupabaseRuntime();
    }
    return url.protocol === "https:" && !isBlockedHttpsHost(hostname);
}

function isBlockedHttpsHost(hostname: string): boolean {
    if (
        isLocalDevelopmentHost(hostname) ||
        hostname.endsWith(".local") ||
        hostname === "metadata.google.internal" ||
        hostname.includes(":")
    ) {
        return true;
    }
    const octets = hostname.split(".").map(Number);
    if (octets.length !== 4 || octets.some((octet) => !Number.isInteger(octet) || octet < 0 || octet > 255)) {
        return false;
    }
    const [first, second, third] = octets as [number, number, number, number];
    return (
        first === 0 ||
        first === 10 ||
        first === 127 ||
