    }
}

import { HttpError } from "../errors.ts";
import { isRecord } from "../records.ts";
import type { ConsentDocumentReference, JsonRecord, PublishedPage, VerifiedConsentDocument } from "../types.ts";
import { pageIdFromSnapshotUrl } from "./url.ts";

const snapshotSchema = "cms-published-page-snapshot-v1";
const maximumContentBytes = 2_000_000;
const hashPattern = /^[a-f0-9]{64}$/;

export function materializeDocumentReferences(value: unknown): {
    documents: ConsentDocumentReference[];
    snapshotOrigin: string | null;
} {
    if (!Array.isArray(value) || value.length > 8) {
        throw new HttpError(400, "documents must be an array of at most 8 entries");
    }
    const documents = value.map((entry, index) => documentReference(entry, index));
    validateCollection(documents);
    return { documents, snapshotOrigin: originOf(documents) };
}

export function materializeResolvedDocuments(value: unknown): {
    documents: Array<VerifiedConsentDocument & { enabled: boolean }>;
    snapshotOrigin: string | null;
} {
    if (!Array.isArray(value) || value.length > 8) {
        throw new HttpError(400, "documents must be an array of at most 8 entries");
    }
    const documents = value.map((entry, index) => resolvedDocument(entry, index));
    validateCollection(documents);
    return { documents, snapshotOrigin: originOf(documents) };
}

export function parsePublishedPageSnapshot(
    value: string,
    expectedPageId: string,
): {
    page: PublishedPage;
    contentHash: string;
} {
    let parsed: unknown;
    try {
        parsed = JSON.parse(value);
    } catch {
        unavailable();
    }
    if (!isRecord(parsed) || parsed.schema !== snapshotSchema || !isRecord(parsed.page)) {
        unavailable();
    }
    const page = pageValue(parsed.page);
    if (page.id !== expectedPageId || typeof parsed.contentHash !== "string" || !hashPattern.test(parsed.contentHash)) {
        unavailable();
    }
    return { page, contentHash: parsed.contentHash };
}

export function unavailable(): never {
    throw new HttpError(409, "CONSENT_DOCUMENT_NOT_AVAILABLE");
}

function documentReference(value: unknown, index: number): ConsentDocumentReference {
    if (!isRecord(value)) {
        throw new HttpError(400, `documents[${index}] is invalid`);
    }
    const publishedSnapshotUrl = text(value.publishedSnapshotUrl, 4096);
    const pageId = pageIdFromSnapshotUrl(publishedSnapshotUrl);
    return {
        key: documentKey(value.key, index),
        enabled: value.enabled !== false,
        label: consentLabel(value.label, index),
        consentText: consentCopy(value.consentText, value.label, index),
        pageId,
        publishedSnapshotUrl,
    };
}

function resolvedDocument(value: unknown, index: number): VerifiedConsentDocument & { enabled: boolean } {
    if (!isRecord(value) || !isRecord(value.page)) {
        throw new HttpError(400, `documents[${index}] is invalid`);
    }
    const page = pageValue(value.page);
    const publishedSnapshotUrl = text(value.page.publishedSnapshotUrl, 4096);
    if (pageIdFromSnapshotUrl(publishedSnapshotUrl) !== page.id) {
        throw new HttpError(422, `documents[${index}].page is not a trusted published snapshot`);
    }
    return {
        key: documentKey(value.key, index),
        enabled: value.enabled !== false,
        label: consentLabel(value.label, index),
        consentText: consentCopy(value.consentText, value.label, index),
        page,
        publishedSnapshotUrl,
        contentHash: "",
    };
}

function validateCollection(documents: Array<{ key: string; publishedSnapshotUrl: string }>): void {
    if (new Set(documents.map((document) => document.key)).size !== documents.length) {
        throw new HttpError(400, "document keys must be unique");
    }
    if (new Set(documents.map((document) => new URL(document.publishedSnapshotUrl).origin)).size > 1) {
        throw new HttpError(422, "consent documents must use one CMS Delivery origin");
    }
}

function originOf(documents: Array<{ publishedSnapshotUrl: string }>): string | null {
    return documents.length ? new URL(documents[0]!.publishedSnapshotUrl).origin : null;
}

function pageValue(value: JsonRecord): PublishedPage {
    const page = {
        id: stringValue(value.id, 512),
        path: stringValue(value.path, 2048),
        title: stringValue(value.title, 500),
        description: stringValue(value.description, 1000, true),
        content: stringValue(value.content, Number.MAX_SAFE_INTEGER),
    };
    if (
        !page.path.startsWith("/") ||
        page.path.startsWith("//") ||
        page.path.includes("\\") ||
        /[\u0000-\u001f\u007f]/u.test(page.path) ||
        new TextEncoder().encode(page.content).byteLength > maximumContentBytes
    ) {
        unavailable();
    }
    return page;
}

function documentKey(value: unknown, index: number): string {
    const result = text(value, 80);
    if (!/^[a-z][a-z0-9_.-]{0,79}$/.test(result)) {
        throw new HttpError(422, `documents[${index}].key is invalid`);
    }
    return result;
}

function consentLabel(value: unknown, index: number): string {
    return documentText(value, 200, `documents[${index}].label`);
}

function consentCopy(value: unknown, label: unknown, index: number): string {
    const result = documentText(value, 1000, `documents[${index}].consentText`);
    if (typeof label !== "string" || !result.includes(label.trim())) {
        throw new HttpError(422, `documents[${index}].consentText must contain label`);
    }
    return result;
}

function documentText(value: unknown, maximum: number, name: string): string {
    if (typeof value !== "string" || !value.trim() || value.length > maximum) {
        throw new HttpError(422, `${name} is invalid`);
    }
    return value.trim();
}

function text(value: unknown, maximum: number): string {
    if (typeof value !== "string" || !value.trim() || value.length > maximum) {
        throw new HttpError(422, "invalid consent document text");
    }
    return value.trim();
}

function stringValue(value: unknown, maximum: number, allowEmpty = false): string {
    if (typeof value !== "string" || value.length > maximum || (!allowEmpty && !value.trim())) {
        unavailable();
    }
    return value;
}

import { HttpError } from "./errors.ts";
import type { JsonRecord } from "./types.ts";

const contextPattern = /^[a-z][a-z0-9_.-]{0,79}$/;
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const versionPattern = /^[a-f0-9]{64}$/;

export async function readJsonObject(request: Request, maximumBytes = 10_000_000): Promise<JsonRecord> {
    const declared = Number(request.headers.get("content-length"));
    if (Number.isFinite(declared) && declared > maximumBytes) {
        throw new HttpError(413, "request body is too large");
    }
    const raw = await request.text();
    if (new TextEncoder().encode(raw).byteLength > maximumBytes) {
        throw new HttpError(413, "request body is too large");
    }
    let value: unknown;
    try {
        value = JSON.parse(raw);
    } catch {
        throw new HttpError(400, "invalid JSON body");
    }
    if (!isRecord(value)) {
        throw new HttpError(400, "body must be an object");
    }
    return value;
}

export function requiredText(body: JsonRecord, name: string, maximum = 4096): string {
    const value = body[name];
    if (typeof value !== "string" || !value.trim() || value.length > maximum) {
        throw new HttpError(400, `${name} is required`);
    }
    return value.trim();
}

export function optionalText(value: string | null, maximum = 512): string | null {
    const result = (value ?? "").trim();
    if (!result) {
        return null;
    }
    if (result.length > maximum) {
        throw new HttpError(400, "query value is too long");
    }
    return result;
}

export function contextKey(value: unknown): string {
    if (typeof value !== "string" || !contextPattern.test(value)) {
        throw new HttpError(400, "contextKey is invalid");
    }
    return value;
}

export function attemptId(value: unknown): string {
    if (typeof value !== "string" || !uuidPattern.test(value)) {
        throw new HttpError(400, "attemptId must be a UUID");
    }
    return value;
}

export function acceptedVersionIds(value: unknown): string[] {
    const entries = typeof value === "string" ? [value] : Array.isArray(value) ? value : [];
    if (!entries.length || entries.length > 8 || entries.some((entry) => typeof entry !== "string")) {
        throw new HttpError(400, "acceptedVersionIds must contain one to 8 version ids");
    }
    const result = entries.map(String);
    if (new Set(result).size !== result.length || result.some((entry) => !versionPattern.test(entry))) {
        throw new HttpError(400, "acceptedVersionIds contains an invalid or duplicate version id");
    }
    return result;
}

export function boundedLimit(value: string | null): number {
    if (!value) {
        return 50;
    }
    const parsed = Number(value);
    if (!Number.isInteger(parsed) || parsed < 1) {
        throw new HttpError(400, "limit must be a positive integer");
    }
    return Math.min(parsed, 100);
}

export function isRecord(value: unknown): value is JsonRecord {
    return typeof value === "object" && value !== null && !Array.isArray(value);
}

import { serviceRoleKey, requiredEnv } from "./env.ts";
import { HttpError } from "./errors.ts";
import { isRecord } from "./records.ts";

const schema = "consent";
const rpcTimeoutMilliseconds = 1_000;
const maximumRpcResponseBytes = 1_048_576;

export async function rpc<T>(name: string, body: Record<string, unknown>): Promise<T> {
    const key = serviceRoleKey();
    const headers = new Headers({ "content-type": "application/json" });
    headers.set("apikey", key);
    if (key.startsWith("sb_")) {
        headers.delete("authorization");
    } else {
        headers.set("authorization", `Bearer ${key}`);
    }
    headers.set("accept-profile", schema);
    headers.set("content-profile", schema);
    const baseUrl = requiredEnv("SUPABASE_URL").replace(/\/$/, "");
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), rpcTimeoutMilliseconds);
    try {
        const response = await fetch(`${baseUrl}/rest/v1/rpc/${encodeURIComponent(name)}`, {
            method: "POST",
            body: JSON.stringify(body),
            headers,
            signal: controller.signal,
        });
        const value = await responseJson(response);
        if (!response.ok) {
            throw restError(response.status, value);
        }
        return value as T;
    } catch (error) {
        if (error instanceof HttpError) {
            throw error;
        }
        throw new HttpError(
            controller.signal.aborted ? 504 : 502,
            controller.signal.aborted ? "consent storage request timed out" : "consent storage request failed",
        );
    } finally {
        clearTimeout(timeout);
    }
}

function restError(status: number, value: unknown): HttpError {
    const message = isRecord(value) && typeof value.message === "string" ? value.message : "database request failed";
    if (message.startsWith("validation:")) {
        return new HttpError(400, message.slice("validation:".length).trim());
    }
    if (message.startsWith("not_found:")) {
        return new HttpError(404, message.slice("not_found:".length).trim());
    }
    if (message.startsWith("conflict:")) {
        return new HttpError(409, message.slice("conflict:".length).trim());
    }
    return new HttpError(502, "consent storage request failed");
}

async function responseJson(response: Response): Promise<unknown> {
    const declared = Number(response.headers.get("content-length"));
    if (Number.isFinite(declared) && declared > maximumRpcResponseBytes) {
        throw new HttpError(502, "consent storage response is too large");
    }
    const reader = response.body?.getReader();
    if (!reader) {
        throw new HttpError(502, "consent storage response is empty");
    }
    const decoder = new TextDecoder();
    let bytes = 0;
    let text = "";
    while (true) {
        const chunk = await reader.read();
        if (chunk.done) {
            break;
        }
        bytes += chunk.value.byteLength;
        if (bytes > maximumRpcResponseBytes) {
            await reader.cancel();
            throw new HttpError(502, "consent storage response is too large");
        }
        text += decoder.decode(chunk.value, { stream: true });
    }
    try {
        return JSON.parse(text + decoder.decode());
    } catch {
        throw new HttpError(502, `consent storage returned invalid JSON (${response.status})`);
    }
}

export type JsonRecord = Record<string, unknown>;

export type PublishedPage = {
    id: string;
    path: string;
    title: string;
    description: string;
    content: string;
};

export type VerifiedConsentDocument = {
    key: string;
    label: string;
    consentText: string;
    publishedSnapshotUrl: string;
    page: PublishedPage;
    contentHash: string;
};

export type ConsentDocumentReference = {
    key: string;
    enabled: boolean;
    label: string;
    consentText: string;
    pageId: string;
    publishedSnapshotUrl: string;
};

import { requireCmsRequest } from "./core/auth.ts";
import { handleError, json, withMethod } from "./core/http.ts";
import { stageAcceptance, commitAcceptance } from "./routes/acceptances.ts";
import { listAcceptances } from "./routes/audit.ts";
import { bootstrapContext, getContext, listContexts, publishContext, syncContext } from "./routes/configuration.ts";
import { getRequirements } from "./routes/requirements.ts";

export async function handleConsentRequest(request: Request): Promise<Response> {
    try {
        requireCmsRequest(request);
        const route = routePath(request);
        if (route === "/health") {
            return await withMethod(request, "GET", async () => json({ ok: true }));
        }
        if (route === "/requirements") {
            return await withMethod(request, "GET", () => getRequirements(request));
        }
        if (route === "/context/sync") {
            return await withMethod(request, "POST", () => syncContext(request));
        }
        if (route === "/context/bootstrap") {
            return await withMethod(request, "POST", () => bootstrapContext(request));
        }
        if (route === "/admin/contexts") {
            return await withMethod(request, "GET", () => listContexts());
        }
        if (route === "/admin/context") {
            return await withMethod(request, "GET", () => getContext(request));
        }
        if (route === "/admin/context/publish") {
            return await withMethod(request, "POST", () => publishContext(request));
        }
        if (route === "/acceptances/stage") {
            return await withMethod(request, "POST", () => stageAcceptance(request));
        }
        if (route === "/acceptances/commit") {
            return await withMethod(request, "POST", () => commitAcceptance(request));
        }
        if (route === "/acceptances") {
            return await withMethod(request, "GET", () => listAcceptances(request));
        }
        return json({ error: "not found" }, 404);
    } catch (error) {
        return handleError(error);
    }
}

function routePath(request: Request): string {
    const pathname = new URL(request.url).pathname.replace(/\/+$/, "");
    const marker = "/cms-consent";
    const index = pathname.indexOf(marker);
    return index === -1 ? pathname || "/" : pathname.slice(index + marker.length) || "/";
}

import { subjectClaimHash } from "../core/auth.ts";
import { HttpError } from "../core/errors.ts";
import { json } from "../core/http.ts";
import { acceptedVersionIds, attemptId, contextKey, readJsonObject, requiredText } from "../core/records.ts";
import { rpc } from "../core/rest.ts";

export async function stageAcceptance(request: Request): Promise<Response> {
    const body = await readJsonObject(request, 16_384);
    const context = contextKey(body.contextKey);
    const hasAttempt = typeof body.attemptId === "string" && Boolean(body.attemptId.trim());
    const hasSubjectClaim = typeof body.subjectClaim === "string" && Boolean(body.subjectClaim.trim());
    const hasAcceptedVersions =
        typeof body.acceptedVersionIds === "string" ||
        (Array.isArray(body.acceptedVersionIds) && body.acceptedVersionIds.length > 0);
    const result = await rpc<Record<string, unknown>>("stage_consent_acceptance", {
        p_context_key: context,
        p_attempt_id: hasAttempt ? attemptId(body.attemptId) : null,
        p_subject_claim_hash: hasSubjectClaim ? await subjectClaimHash(requiredText(body, "subjectClaim", 320)) : null,
        p_accepted_version_ids: hasAcceptedVersions ? acceptedVersionIds(body.acceptedVersionIds) : [],
    });
    if (result.state === "version_changed") {
        throw new HttpError(409, "CONSENT_DOCUMENT_VERSION_CHANGED");
    }
    return json(result);
}

export async function commitAcceptance(request: Request): Promise<Response> {
    const body = await readJsonObject(request, 16_384);
    const context = contextKey(body.contextKey);
    const cmsUserId = requiredText(body, "cmsUserId", 512);
    const hasAttempt = typeof body.attemptId === "string" && Boolean(body.attemptId.trim());
    const parsedAttempt = hasAttempt ? attemptId(body.attemptId) : null;
    const claimHash = hasAttempt ? await subjectClaimHash(requiredText(body, "subjectClaim", 320)) : null;
    const accepted = hasAttempt ? acceptedVersionIds(body.acceptedVersionIds) : [];
    const result = await rpc<Record<string, unknown>>("commit_consent_acceptance", {
        p_context_key: context,
        p_attempt_id: parsedAttempt,
        p_subject_claim_hash: claimHash,
        p_accepted_version_ids: accepted,
        p_cms_user_id: cmsUserId,
    });
    return json(result);
}

import { HttpError } from "../core/errors.ts";
import { json } from "../core/http.ts";
import { boundedLimit, contextKey, optionalText } from "../core/records.ts";
import { rpc } from "../core/rest.ts";

const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

export async function listAcceptances(request: Request): Promise<Response> {
    const params = new URL(request.url).searchParams;
    const contextValue = optionalText(params.get("context"), 80);
    const cmsUserId = optionalText(params.get("cmsUserId"), 512);
    const beforeCommittedAt = optionalText(params.get("beforeCommittedAt"), 64);
    const beforeId = optionalText(params.get("beforeId"), 36);
    if ((beforeCommittedAt === null) !== (beforeId === null)) {
        throw new HttpError(400, "both audit cursor fields are required");
    }
    if (beforeCommittedAt && !Number.isFinite(Date.parse(beforeCommittedAt))) {
        throw new HttpError(400, "beforeCommittedAt is invalid");
    }
    if (beforeId && !uuidPattern.test(beforeId)) {
        throw new HttpError(400, "beforeId is invalid");
    }
    const result = await rpc<Record<string, unknown>>("list_consent_acceptances", {
        p_context_key: contextValue ? contextKey(contextValue) : null,
        p_cms_user_id: cmsUserId,
        p_before_committed_at: beforeCommittedAt,
        p_before_id: beforeId,
        p_limit: boundedLimit(params.get("limit")),
    });
    return json(result);
}

import { HttpError } from "../core/errors.ts";
import { json } from "../core/http.ts";
import {
    fetchResolvedDocuments,
    hashResolvedDocuments,
    materializeResolvedDocuments,
} from "../core/publishedPages/index.ts";
import { contextKey, isRecord, readJsonObject } from "../core/records.ts";
import { rpc } from "../core/rest.ts";

export async function bootstrapContext(request: Request): Promise<Response> {
    const body = await readJsonObject(request);
    const result = await rpc<Record<string, unknown>>("bootstrap_consent_context", {
        p_context_key: contextKey(body.contextKey),
        p_actor_id: "cms-integration-bootstrap",
    });
    return json(result);
}

export async function listContexts(): Promise<Response> {
    return json(await rpc<Record<string, unknown>>("list_consent_contexts", {}));
}

export async function getContext(request: Request): Promise<Response> {
    const value = new URL(request.url).searchParams.get("context")?.trim() ?? "";
    if (!value) {
        return json({
            contextKey: "",
            enabled: false,
            status: "inactive",
            revision: "new",
            approvedSnapshotOrigin: null,
            updatedAt: null,
            documents: [],
        });
    }
    const result = await rpc<Record<string, unknown>>("consent_context_management_projection", {
        p_context_key: contextKey(value),
    });
    return json(result);
}

export async function publishContext(request: Request): Promise<Response> {
    const body = await readJsonObject(request);
    const context = contextKey(body.contextKey);
    const expectedRevision = revision(body.expectedRevision);
    const actorId = adminActor(request);
    if (body.enabled !== true) {
        const name = expectedRevision === "new" ? "publish_consent_context" : "disable_consent_context";
        const parameters =
            expectedRevision === "new"
                ? {
                      p_context_key: context,
                      p_enabled: false,
                      p_snapshot_origin: null,
                      p_documents: [],
                      p_actor_id: actorId,
                      p_expected_revision: expectedRevision,
                  }
                : {
                      p_context_key: context,
                      p_actor_id: actorId,
                      p_expected_revision: expectedRevision,
                  };
        return json(await rpc<Record<string, unknown>>(name, parameters));
    }
    const materialized = await fetchResolvedDocuments(body.documents);
    if (!materialized.documents.some((document) => document.enabled)) {
        throw new HttpError(422, "enabled consent requires at least one document");
    }
    const result = await rpc<Record<string, unknown>>("publish_consent_context", {
        p_context_key: context,
        p_enabled: true,
        p_snapshot_origin: materialized.snapshotOrigin,
        p_documents: materialized.documents,
        p_actor_id: actorId,
        p_expected_revision: expectedRevision,
    });
    return json(result);
}

export async function syncContext(request: Request): Promise<Response> {
    const body = await readJsonObject(request);
    let configuration = body;
    if (body.configuration !== undefined) {
        if (typeof body.configuration !== "string" || body.configuration.length > 10_000_000) {
            throw new HttpError(400, "configuration must be a bounded JSON string");
        }
        let parsed: unknown;
        try {
            parsed = JSON.parse(body.configuration);
        } catch {
            throw new HttpError(400, "configuration must contain valid JSON");
        }
        if (!isRecord(parsed)) {
            throw new HttpError(400, "configuration must contain an object");
        }
        configuration = parsed;
    }
    if (typeof configuration.enabled !== "boolean") {
        throw new HttpError(400, "enabled must be a boolean");
    }
    const context = contextKey(configuration.contextKey);
    const materialized = materializeResolvedDocuments(configuration.documents);
    const documents = await hashResolvedDocuments(materialized.documents);
    if (configuration.enabled && !documents.some((document) => document.enabled)) {
        throw new HttpError(422, "enabled consent requires at least one document");
    }
    const result = await rpc<Record<string, unknown>>("sync_consent_context", {
        p_context_key: context,
        p_enabled: configuration.enabled,
        p_snapshot_origin: materialized.snapshotOrigin,
        p_documents: documents,
        p_actor_id: "cms-integration-sync",
    });
    return json(result);
}

function adminActor(request: Request): string {
    const value = request.headers.get("x-cms-user-id")?.trim() ?? "";
    if (!value || value.length > 512) {
        throw new HttpError(401, "CMS administrator identity is required");
    }
    return value;
}

function revision(value: unknown): string {
    if (typeof value !== "string" || !/^(new|[1-9][0-9]{0,19})$/.test(value)) {
        throw new HttpError(400, "expectedRevision is invalid");
    }
    return value;
}

import { json } from "../core/http.ts";
import { contextKey } from "../core/records.ts";
import { rpc } from "../core/rest.ts";

export async function getRequirements(request: Request): Promise<Response> {
    const context = contextKey(new URL(request.url).searchParams.get("context"));
    const result = await rpc<Record<string, unknown>>("consent_requirements_projection", {
        p_context_key: context,
    });
    return json(result);
}

