create or replace function consent.commit_consent_acceptance(
    p_context_key text,
    p_attempt_id uuid,
    p_subject_claim_hash text,
    p_accepted_version_ids text[],
    p_cms_user_id text
)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
declare
    v_context_enabled boolean;
    v_intent consent.acceptance_intents%rowtype;
    v_intent_ids text[];
    v_acceptance consent.acceptances%rowtype;
    v_acceptance_ids text[];
    v_copied integer;
begin
    if length(btrim(coalesce(p_cms_user_id, ''))) not between 1 and 512 then
        raise exception 'validation: CMS subject id is required';
    end if;
    select enabled into v_context_enabled
    from consent.contexts
    where context_key = p_context_key;
    if not found then
        raise exception 'not_found: consent context';
    end if;
    if p_attempt_id is null then
        if not v_context_enabled then
            return jsonb_build_object(
                'committed', false,
                'acceptanceId', null,
                'cmsUserId', p_cms_user_id,
                'acceptedAt', null
            );
        end if;
        raise exception 'validation: consent attempt is required';
    end if;
    perform pg_advisory_xact_lock(hashtextextended(
        'consent-attempt:' || p_context_key || ':' || p_attempt_id::text,
        0
    ));
    if coalesce(p_subject_claim_hash, '') !~ '^[a-f0-9]{64}$' then
        raise exception 'validation: consent subject claim is required';
    end if;

    select * into v_acceptance
    from consent.acceptances
    where context_key = p_context_key and attempt_id = p_attempt_id;
    if found then
        select coalesce(array_agg(version_id order by version_id), '{}'::text[])
        into v_acceptance_ids
        from consent.acceptance_documents
        where acceptance_id = v_acceptance.id;
        if cardinality(v_acceptance_ids) = 0
            or v_acceptance.cms_user_id <> p_cms_user_id
            or v_acceptance.subject_claim_hash <> p_subject_claim_hash
            or coalesce(cardinality(p_accepted_version_ids), 0) <> cardinality(v_acceptance_ids)
            or (select count(distinct id) from unnest(p_accepted_version_ids) id)
                <> cardinality(v_acceptance_ids)
            or exists (
                select 1 from unnest(v_acceptance_ids) accepted(id)
                where not accepted.id = any(p_accepted_version_ids)
            ) then
            raise exception 'conflict: consent attempt belongs to another subject or evidence';
        end if;
        return jsonb_build_object(
            'committed', true,
            'acceptanceId', v_acceptance.id::text,
            'cmsUserId', v_acceptance.cms_user_id,
            'acceptedAt', v_acceptance.accepted_at
        );
    end if;

    select * into v_intent
    from consent.acceptance_intents
    where context_key = p_context_key and attempt_id = p_attempt_id
    for update;
    if not found then
        if not v_context_enabled then
            return jsonb_build_object(
                'committed', false,
                'acceptanceId', null,
                'cmsUserId', p_cms_user_id,
                'acceptedAt', null
            );
        end if;
        raise exception 'conflict: consent attempt was not staged';
    end if;
    if v_intent.expires_at <= now()
        or v_intent.subject_claim_hash is distinct from p_subject_claim_hash then
        raise exception 'conflict: consent attempt is invalid or expired';
    end if;
    select coalesce(array_agg(version_id order by version_id), '{}'::text[])
    into v_intent_ids
    from consent.acceptance_intent_documents
    where context_key = p_context_key and attempt_id = p_attempt_id;
    if cardinality(v_intent_ids) = 0
        or coalesce(cardinality(p_accepted_version_ids), 0) <> cardinality(v_intent_ids)
        or (select count(distinct id) from unnest(p_accepted_version_ids) id)
            <> cardinality(v_intent_ids)
        or exists (
            select 1 from unnest(v_intent_ids) required(id)
            where not required.id = any(p_accepted_version_ids)
        ) then
        raise exception 'conflict: consent evidence differs from the staged attempt';
    end if;

    insert into consent.acceptances (
        context_key, attempt_id, cms_user_id, subject_claim_hash, accepted_at
    ) values (
        p_context_key, p_attempt_id, p_cms_user_id,
        p_subject_claim_hash, v_intent.accepted_at
    ) returning * into v_acceptance;
    insert into consent.acceptance_documents (
        acceptance_id, context_key, document_key, version_id, content_hash
    )
    select v_acceptance.id, context_key, document_key, version_id, content_hash
    from consent.acceptance_intent_documents
    where context_key = p_context_key and attempt_id = p_attempt_id;
    get diagnostics v_copied = row_count;
    if v_copied <> cardinality(v_intent_ids) then
        raise exception 'conflict: consent evidence could not be committed completely';
    end if;
    delete from consent.acceptance_intents
    where context_key = p_context_key and attempt_id = p_attempt_id;
    return jsonb_build_object(
        'committed', true,
        'acceptanceId', v_acceptance.id::text,
        'cmsUserId', v_acceptance.cms_user_id,
        'acceptedAt', v_acceptance.accepted_at
    );
end;
$$;

connectors/supabase/sql/commands/context.content:
create or replace function consent.consent_context_management_projection(p_context_key text)
returns jsonb
language plpgsql
stable
security invoker
set search_path = ''
as $$
declare
    v_result jsonb;
begin
    select jsonb_build_object(
        'contextKey', context.context_key,
        'enabled', context.enabled,
        'status', case when context.enabled then 'active' else 'inactive' end,
        'revision', context.xmin::text || ':' || context.ctid::text,
        'approvedSnapshotOrigin', context.approved_snapshot_origin,
        'updatedAt', context.updated_at,
        'documents', coalesce((
            select jsonb_agg(jsonb_build_object(
                'key', document.document_key,
                'enabled', document.enabled,
                'position', document.sort_order,
                'label', document.label,
                'consentText', document.consent_text,
                'pageId', document.cms_page_id,
                'publishedSnapshotUrl', document.published_snapshot_url,
                'versionId', document.current_version_id,
                'contentHash', version.content_hash
            ) order by document.sort_order, document.document_key)
            from consent.documents document
            left join consent.document_versions version
              on version.context_key = document.context_key
             and version.document_key = document.document_key
             and version.version_id = document.current_version_id
            where document.context_key = context.context_key
        ), '[]'::jsonb)
    ) into v_result
    from consent.contexts context
    where context.context_key = p_context_key;
    if v_result is null then
        raise exception 'not_found: consent context';
    end if;
    return v_result;
end;
$$;

create or replace function consent.list_consent_contexts()
returns jsonb
language sql
stable
security invoker
set search_path = ''
as $$
    with items as (
        select jsonb_build_object(
            'id', context.context_key,
            'contextKey', context.context_key,
            'enabled', context.enabled,
            'status', case when context.enabled then 'active' else 'inactive' end,
            'revision', context.xmin::text || ':' || context.ctid::text,
            'documentCount', count(document.document_key) filter (where document.enabled),
            'updatedAt', context.updated_at
        ) as item, context.updated_at, context.context_key
        from consent.contexts context
        left join consent.documents document on document.context_key = context.context_key
        group by context.context_key, context.xmin, context.ctid
    )
    select jsonb_build_object(
        'items', coalesce(jsonb_agg(item order by updated_at desc, context_key), '[]'::jsonb),
        'total', count(*)
    )
    from items;
$$;

create or replace function consent.bootstrap_consent_context(
    p_context_key text,
    p_actor_id text
)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
begin
    if p_context_key !~ '^[a-z][a-z0-9_.-]{0,79}$'
        or length(btrim(coalesce(p_actor_id, ''))) not between 1 and 512 then
        raise exception 'validation: invalid consent context bootstrap';
    end if;
    perform pg_advisory_xact_lock(hashtextextended('consent:' || p_context_key, 0));
    insert into consent.contexts (context_key, enabled, configured_by)
    values (p_context_key, false, p_actor_id)
    on conflict (context_key) do nothing;
    return consent.consent_context_management_projection(p_context_key);
end;
$$;

create or replace function consent.publish_consent_context(
    p_context_key text,
    p_enabled boolean,
    p_snapshot_origin text,
    p_documents jsonb,
    p_actor_id text,
    p_expected_revision text
)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
declare
    v_revision text;
begin
    if length(btrim(coalesce(p_expected_revision, ''))) not between 1 and 32 then
        raise exception 'validation: expectedRevision is invalid';
    end if;
    perform pg_advisory_xact_lock(hashtextextended('consent:' || p_context_key, 0));
    select xmin::text || ':' || ctid::text into v_revision
    from consent.contexts
    where context_key = p_context_key
    for update;
    if found and v_revision <> p_expected_revision then
        raise exception 'conflict: CONSENT_CONTEXT_REVISION_CHANGED';
    end if;
    if not found and p_expected_revision <> 'new' then
        raise exception 'conflict: CONSENT_CONTEXT_REVISION_CHANGED';
    end if;
    perform consent.sync_consent_context(
        p_context_key, p_enabled, p_snapshot_origin, p_documents, p_actor_id
    );
    return consent.consent_context_management_projection(p_context_key);
end;
$$;

create or replace function consent.disable_consent_context(
    p_context_key text,
    p_actor_id text,
    p_expected_revision text
)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
begin
    if length(btrim(coalesce(p_expected_revision, ''))) not between 1 and 32
        or p_expected_revision = 'new' then
        raise exception 'validation: expectedRevision is invalid';
    end if;
    perform pg_advisory_xact_lock(hashtextextended('consent:' || p_context_key, 0));
    update consent.contexts
    set enabled = false,
        configured_by = p_actor_id,
        updated_at = now()
    where context_key = p_context_key
      and xmin::text || ':' || ctid::text = p_expected_revision;
    if not found then
        if exists (select 1 from consent.contexts where context_key = p_context_key) then
            raise exception 'conflict: CONSENT_CONTEXT_REVISION_CHANGED';
        end if;
        raise exception 'not_found: consent context';
    end if;
    return consent.consent_context_management_projection(p_context_key);
end;
$$;

create or replace function consent.materialize_consent_documents(
    p_context_key text,
    p_documents jsonb,
    p_actor_id text
)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
declare
    v_context consent.contexts%rowtype;
    v_document jsonb;
    v_config consent.documents%rowtype;
    v_page jsonb;
    v_key text;
    v_hash text;
    v_version_id text;
    v_count integer;
begin
    perform pg_advisory_xact_lock(hashtextextended('consent:' || p_context_key, 0));
    select * into v_context
    from consent.contexts
    where context_key = p_context_key
    for update;
    if not found then
        raise exception 'not_found: consent context';
    end if;
    if not v_context.enabled then
        return consent.consent_requirements_projection(p_context_key);
    end if;
    if jsonb_typeof(p_documents) <> 'array' or jsonb_array_length(p_documents) > 8 then
        raise exception 'validation: verified documents must be an array of at most 8 entries';
    end if;
    select count(*) into v_count
    from consent.documents
    where context_key = p_context_key and enabled;
    if v_count = 0 or v_count <> jsonb_array_length(p_documents) then
        raise exception 'conflict: CONSENT_DOCUMENT_NOT_AVAILABLE';
    end if;
    if (select count(distinct value->>'key') from jsonb_array_elements(p_documents)) <> v_count then
        raise exception 'conflict: CONSENT_DOCUMENT_NOT_AVAILABLE';
    end if;

    for v_document in select value from jsonb_array_elements(p_documents)
    loop
        v_key := coalesce(v_document->>'key', '');
        select * into v_config
        from consent.documents
        where context_key = p_context_key and document_key = v_key and enabled
        for update;
        if not found
            or v_document->>'label' is distinct from v_config.label
            or v_document->>'consentText' is distinct from v_config.consent_text
            or v_document->>'publishedSnapshotUrl' is distinct from v_config.published_snapshot_url then
            raise exception 'conflict: CONSENT_DOCUMENT_NOT_AVAILABLE';
        end if;
        v_page := v_document->'page';
        if jsonb_typeof(v_page) <> 'object'
            or v_page->>'id' is distinct from v_config.cms_page_id
            or left(coalesce(v_page->>'path', ''), 1) <> '/'
            or left(coalesce(v_page->>'path', ''), 2) = '//'
            or strpos(coalesce(v_page->>'path', ''), chr(92)) > 0
            or coalesce(v_page->>'path', '') ~ '[[:cntrl:]]'
            or length(coalesce(v_page->>'path', '')) > 2048
            or length(btrim(coalesce(v_page->>'title', ''))) not between 1 and 500
            or length(coalesce(v_page->>'description', '')) > 1000
            or length(btrim(coalesce(v_page->>'content', ''))) = 0
            or octet_length(coalesce(v_page->>'content', '')) > 2000000 then
            raise exception 'conflict: CONSENT_DOCUMENT_NOT_AVAILABLE';
        end if;
        v_hash := consent.published_page_hash(v_page);
        if v_hash is distinct from v_document->>'contentHash' then
            raise exception 'conflict: CONSENT_DOCUMENT_NOT_AVAILABLE';
        end if;
        v_version_id := consent.document_version_id(
            p_context_key, v_key, v_config.label, v_config.consent_text,
            v_config.published_snapshot_url, v_hash
        );
        insert into consent.document_versions (
            context_key, document_key, version_id, label, consent_text,
            cms_page_id, page_path, page_title, page_description,
            page_content, page_snapshot, published_snapshot_url,
            content_hash, materialized_by
        ) values (
            p_context_key, v_key, v_version_id, v_config.label, v_config.consent_text,
            v_config.cms_page_id, v_page->>'path', v_page->>'title',
            coalesce(v_page->>'description', ''), v_page->>'content', v_page,
            v_config.published_snapshot_url, v_hash, p_actor_id
        ) on conflict (context_key, document_key, version_id) do nothing;
        update consent.documents
        set current_version_id = v_version_id, updated_at = now()
        where context_key = p_context_key
          and document_key = v_key
          and current_version_id is distinct from v_version_id;
    end loop;
    return consent.consent_requirements_projection(p_context_key);
end;
$$;

create or replace function consent.sync_consent_context(
    p_context_key text,
    p_enabled boolean,
    p_snapshot_origin text,
    p_documents jsonb,
    p_actor_id text
)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
declare
    v_document jsonb;
    v_page jsonb;
    v_key text;
    v_label text;
    v_consent_text text;
    v_document_enabled boolean;
    v_position integer;
    v_enabled_documents jsonb;
    v_requirements jsonb;
begin
    if p_context_key !~ '^[a-z][a-z0-9_.-]{0,79}$'
        or length(btrim(coalesce(p_actor_id, ''))) not between 1 and 512 then
        raise exception 'validation: invalid consent context configuration';
    end if;
    if p_snapshot_origin is not null
        and (length(p_snapshot_origin) > 2048 or p_snapshot_origin !~ '^https?://[^/]+$') then
        raise exception 'validation: invalid consent snapshot origin';
    end if;
    if jsonb_typeof(p_documents) <> 'array' or jsonb_array_length(p_documents) > 8 then
        raise exception 'validation: consent documents must be an array of at most 8 entries';
    end if;
    if (select count(distinct value->>'key') from jsonb_array_elements(p_documents))
        <> jsonb_array_length(p_documents) then
        raise exception 'validation: consent document keys must be unique';
    end if;

    perform pg_advisory_xact_lock(hashtextextended('consent:' || p_context_key, 0));
    insert into consent.contexts (
        context_key, enabled, approved_snapshot_origin, configured_by
    ) values (
        p_context_key, p_enabled, p_snapshot_origin, p_actor_id
    ) on conflict (context_key) do update set
        enabled = excluded.enabled,
        approved_snapshot_origin = excluded.approved_snapshot_origin,
        configured_by = excluded.configured_by,
        updated_at = now();

    update consent.documents
    set enabled = false, configured_by = p_actor_id, updated_at = now()
    where context_key = p_context_key;

    for v_document, v_position in
        select entry.value, entry.position::integer - 1
        from jsonb_array_elements(p_documents) with ordinality entry(value, position)
    loop
        if jsonb_typeof(v_document) <> 'object'
            or (v_document ? 'enabled' and jsonb_typeof(v_document->'enabled') <> 'boolean') then
            raise exception 'validation: invalid consent document';
        end if;
        v_key := btrim(coalesce(v_document->>'key', ''));
        v_label := btrim(coalesce(v_document->>'label', ''));
        v_consent_text := btrim(coalesce(v_document->>'consentText', ''));
        v_document_enabled := coalesce((v_document->>'enabled')::boolean, true);
        v_page := v_document->'page';
        if v_key !~ '^[a-z][a-z0-9_.-]{0,79}$'
            or length(v_label) not between 1 and 200
            or length(v_consent_text) not between 1 and 1000
            or jsonb_typeof(v_page) <> 'object'
            or length(btrim(coalesce(v_page->>'id', ''))) not between 1 and 512
            or length(coalesce(v_document->>'publishedSnapshotUrl', '')) not between 1 and 4096 then
            raise exception 'validation: invalid consent document';
        end if;
        if strpos(v_consent_text, v_label) = 0 then
            raise exception 'validation: consentText must contain label';
        end if;
        if p_snapshot_origin is null
            or v_document->>'publishedSnapshotUrl' not like p_snapshot_origin || '/%' then
            raise exception 'validation: consent snapshot URL does not use the approved origin';
        end if;
        insert into consent.documents (
            context_key, document_key, enabled, sort_order, label, consent_text,
            cms_page_id, published_snapshot_url, configured_by
        ) values (
            p_context_key, v_key, v_document_enabled, v_position, v_label,
            v_consent_text, v_page->>'id',
            v_document->>'publishedSnapshotUrl', p_actor_id
        ) on conflict (context_key, document_key) do update set
            enabled = excluded.enabled,
            sort_order = excluded.sort_order,
            label = excluded.label,
            consent_text = excluded.consent_text,
            cms_page_id = excluded.cms_page_id,
            published_snapshot_url = excluded.published_snapshot_url,
            configured_by = excluded.configured_by,
            updated_at = now();
    end loop;

    select coalesce(jsonb_agg(value order by position), '[]'::jsonb)
    into v_enabled_documents
    from jsonb_array_elements(p_documents) with ordinality entry(value, position)
    where coalesce((value->>'enabled')::boolean, true);
    if p_enabled and jsonb_array_length(v_enabled_documents) = 0 then
        raise exception 'validation: enabled consent requires at least one document';
    end if;
    v_requirements := consent.materialize_consent_documents(
        p_context_key, v_enabled_documents, p_actor_id
    );
    return jsonb_build_object(
        'contextKey', p_context_key,
        'enabled', p_enabled,
        'documentCount', jsonb_array_length(v_requirements->'documents')
    );
end;
$$;

connectors/supabase/sql/commands/stage-a.content:
create or replace function consent.stage_consent_acceptance(
    p_context_key text,
    p_attempt_id uuid,
    p_subject_claim_hash text,
    p_accepted_version_ids text[]
)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
declare
    v_requirements jsonb;
    v_required_ids text[];
    v_existing consent.acceptance_intents%rowtype;
    v_existing_ids text[];
    v_committed consent.acceptances%rowtype;
    v_committed_ids text[];
    v_inserted integer;
begin
    if p_attempt_id is not null then
        perform pg_advisory_xact_lock(hashtextextended(
            'consent-attempt:' || p_context_key || ':' || p_attempt_id::text,
            0
        ));
    end if;
    if p_attempt_id is not null then
        select * into v_committed
        from consent.acceptances
        where context_key = p_context_key and attempt_id = p_attempt_id;
        if found then
            select coalesce(array_agg(version_id order by version_id), '{}'::text[])
            into v_committed_ids
            from consent.acceptance_documents
            where acceptance_id = v_committed.id;
            if cardinality(v_committed_ids) = 0
                or v_committed.subject_claim_hash is distinct from p_subject_claim_hash
                or coalesce(cardinality(p_accepted_version_ids), 0) <> cardinality(v_committed_ids)
                or (select count(distinct id) from unnest(p_accepted_version_ids) id)
                    <> cardinality(v_committed_ids)
                or exists (
                    select 1 from unnest(v_committed_ids) committed(id)
                    where not committed.id = any(p_accepted_version_ids)
                ) then
                raise exception 'conflict: consent attempt belongs to different evidence';
            end if;
            return jsonb_build_object(
                'staged', true,
                'attemptId', p_attempt_id::text,
                'requiredCount', cardinality(v_committed_ids)
            );
        end if;
    end if;

    if p_attempt_id is not null then
        select * into v_existing
        from consent.acceptance_intents
        where context_key = p_context_key and attempt_id = p_attempt_id
        for update;
        if found then
            select coalesce(array_agg(version_id order by version_id), '{}'::text[])
            into v_existing_ids
            from consent.acceptance_intent_documents
            where context_key = p_context_key and attempt_id = p_attempt_id;
            if cardinality(v_existing_ids) = 0
                or v_existing.subject_claim_hash is distinct from p_subject_claim_hash
                or v_existing.expires_at <= now()
                or coalesce(cardinality(p_accepted_version_ids), 0) <> cardinality(v_existing_ids)
                or (select count(distinct id) from unnest(p_accepted_version_ids) id)
                    <> cardinality(v_existing_ids)
                or exists (
                    select 1 from unnest(v_existing_ids) staged(id)
                    where not staged.id = any(p_accepted_version_ids)
                ) then
                raise exception 'conflict: consent attempt was already used with different evidence';
            end if;
            return jsonb_build_object(
                'staged', true,
                'attemptId', p_attempt_id::text,
                'requiredCount', cardinality(v_existing_ids)
            );
        end if;
    end if;

    perform pg_advisory_xact_lock(hashtextextended('consent:' || p_context_key, 0));
    v_requirements := consent.consent_requirements_projection(p_context_key);
    if not coalesce((v_requirements->>'enabled')::boolean, false) then
        return jsonb_build_object(
            'staged', false,
            'attemptId', coalesce(p_attempt_id::text, ''),
            'requiredCount', 0
        );
    end if;
    perform consent.prune_expired_consent_intents(p_context_key, 100);
    if p_attempt_id is null or p_subject_claim_hash !~ '^[a-f0-9]{64}$' then
        raise exception 'validation: consent attempt and subject claim are required';
    end if;
    select coalesce(array_agg(value->>'versionId' order by value->>'versionId'), '{}'::text[])
    into v_required_ids
    from jsonb_array_elements(v_requirements->'documents');
    if cardinality(v_required_ids) = 0 then
        raise exception 'conflict: enabled consent has no materialized documents';
    end if;

    if coalesce(cardinality(p_accepted_version_ids), 0) <> cardinality(v_required_ids)
        or (select count(distinct id) from unnest(p_accepted_version_ids) id)
            <> cardinality(v_required_ids)
        or exists (
            select 1 from unnest(v_required_ids) required(id)
            where not required.id = any(p_accepted_version_ids)
        ) then
        return jsonb_build_object(
            'state', 'version_changed',
            'staged', false,
            'attemptId', p_attempt_id::text,
            'requiredCount', cardinality(v_required_ids)
        );
    end if;

    insert into consent.acceptance_intents (
        context_key, attempt_id, subject_claim_hash
    ) values (
        p_context_key, p_attempt_id, p_subject_claim_hash
    );
    insert into consent.acceptance_intent_documents (
        context_key, attempt_id, document_key, version_id, content_hash
    )
    select p_context_key, p_attempt_id, version.document_key,
        version.version_id, version.content_hash
    from consent.document_versions version
    where version.context_key = p_context_key
      and version.version_id = any(v_required_ids);
    get diagnostics v_inserted = row_count;
    if v_inserted <> cardinality(v_required_ids) then
        raise exception 'conflict: consent evidence could not be staged completely';
    end if;
    return jsonb_build_object(
        'staged', true,
        'attemptId', p_attempt_id::text,
        'requiredCount', cardinality(v_required_ids)
    );
end;
$$;

connectors/supabase/sql/model/foundation.content:
create schema if not exists consent;
create schema if not exists extensions;

create extension if not exists pgcrypto with schema extensions;

comment on schema consent is
    'Versioned consent configuration and immutable acceptance evidence.';

revoke all on schema consent from public;
revoke all on schema consent from anon;
revoke all on schema consent from authenticated;
grant usage on schema consent to service_role;
grant usage on schema extensions to service_role;

